/* cppi::39fff207ebe9acad4287af778bec1f9668a7590b8dfca6eefb541866d9ec3b1f */
SELECT COUNT(*) FROM (SELECT pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name, SUM(market_value_reporting_currency) AS mv_rc, SUM(period_result_node_by_node_reporting_currency) AS pnl_rc, CASE WHEN ref.abor_instrument_type_id IN ('Equity', 'GDR/ADR', 'Bond', 'CD', 'CP', 'ABS', 'Index certificate') AND ref.abor_security_group_name NOT IN ('CPPIB Internal Bond', 'CPPIB Internal Term Deposit') AND SUM(market_value_reporting_currency) >= 0 THEN 'long' ELSE 'short' END AS long_short FROM performance.scd_performance_seclvl pnl LEFT JOIN reference.scd_securities ref ON pnl.aggregation_level_3 = ref.abor_security_id AND ref.business_date = (SELECT MAX(business_date) FROM reference.scd_securities) WHERE pnl.business_date BETWEEN '2024-04-01' AND '2025-03-31' AND aggregation_level_1 IN (SELECT model_portfolio FROM performance.scd_performance_invstr_flatten pif WHERE pif.business_date = (SELECT MAX(business_date) FROM performance.scd_performance_invstr_flatten) AND investmentstructurelevel3 IN ('EPM', 'Macro Strategies', 'Quantitative Strategies & Risk Premia') AND investmentstructurelevel4 IN ('EPM Core', 'EPM Corporate Expenses', 'EPM Legacy', 'MS CMF Common', 'Legacy')) GROUP BY pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name
) dbvrcnt

/* cppi::39fff207ebe9acad4287af778bec1f9668a7590b8dfca6eefb541866d9ec3b1f */
